function solve(x){
  var c=x.config||{}, ev=x.event||{}, s=x.state;
  if(!s)s={o:[],e:{},v:{},d:{}};
  var o=s.o,e=s.e,v=s.v,d=s.d,k=ev.key, status='ignored',value=null,fl=[];
  function has(a,z){return Object.prototype.hasOwnProperty.call(a,z)}
  function touch(z){var i=o.indexOf(z);if(i>=0)o.splice(i,1);o.push(z)}
  function remove(z){var i=o.indexOf(z);if(i>=0)o.splice(i,1);delete e[z]}
  function cleanSlot(){for(var i=0;i<o.length;i++)if(!e[o[i]].dirty)return o[i];return null}
  function make(z,val,dirty){e[z]={value:val,version:v[z]||0,dirty:!!dirty,flushed:false};o.push(z)}
  if(ev.type==='write'){
    v[k]=(v[k]||0)+1;
    if(has(e,k)){e[k].value=ev.value;e[k].version=v[k];e[k].dirty=true;e[k].flushed=false;touch(k);status='written'}
    else {if(o.length<(c.slots||0)){make(k,ev.value,true);status='written'}else{var q=cleanSlot();if(q!==null){remove(q);make(k,ev.value,true);status='written'}else status='blocked'}}
  }else if(ev.type==='read'){
    if(has(e,k)){value=e[k].value;touch(k);status='hit'}
    else if(has(d,k)){value=d[k];var q=null;if(o.length>=(c.slots||0))q=cleanSlot();if(o.length<(c.slots||0)||(q!==null)){if(q!==null)remove(q);make(k,value,false)}status='durable'}
    else status='miss'
  }else if(ev.type==='flush'){
    if(has(e,k)&&e[k].dirty){var z=e[k];z.flushed=true;fl.push({key:k,value:z.value,version:z.version});status='flushed'}
  }else if(ev.type==='ack'){
    if(has(e,k)){var z=e[k];if(z.dirty&&z.version===ev.version&&z.flushed){d[k]=z.value;z.dirty=false;z.flushed=false;status='persisted'}}
  }else if(ev.type==='evict'){
    if(!has(e,k))status='missing';else if(e[k].dirty)status='blocked';else{remove(k);status='evicted'}
  }
  var dirty=o.filter(function(z){return e[z].dirty}).sort();
  var cached=o.slice(),durable={};Object.keys(d).sort().forEach(function(z){durable[z]=d[z]});
  return {state:s,output:{status:status,value:value,flush:fl,cached:cached,dirty:dirty,durable:durable}};
}
